// Учебный маршрут для браузерного теста экрана «С нуля»: подставляется вместо c-zero-en.js, поэтому тест не зависит от настоящих уроков.
// Пять уроков по цепочке; в каждом по восемь заданий разных видов (две подсказки), вопросы содержат номер урока, чтобы их можно было отличить.
import { choose, listen, typed, order, match, read } from './zero-kit.js';

const lesson = (n, needs, o = {}) => {
  const id = `ez-0${n}`;
  return {
    id, title: `Тестовый урок ${n}`, minutes: 3, stage: n < 4 ? 'Звуки' : 'Алфавит', needs, intro: '',
    goal: `выполнить задания тестового урока ${n}`,
    body: [`Это первый абзац тестового урока ${n}. Он нужен, чтобы проверить показ текста.`, `Второй абзац урока ${n}: короткий и простой, без сложных слов.`],
    task: `Скажи вслух номер урока ${n} и повтори его три раза.`,
    cards: [[`Какой это номер урока ${n}?`, String(n)], [`Что делать после урока ${n}?`, 'Пройти проверку']],
    drills: [
      choose(`Урок ${n}: сколько будет один плюс один?`, '2', ['3', '11'], { hint: 'Это два', explain: 'Один плюс один равно два.' }),
      choose(`Урок ${n}: какой цвет у снега?`, 'Белый', ['Чёрный', 'Красный', 'Зелёный'], { hint: 'Он как молоко', explain: 'Снег белый.' }),
      listen('cat', 'cat', ['cut', 'cot'], { q: `Урок ${n}: какое слово ты услышал?`, explain: 'Слово cat.' }),
      typed(`Урок ${n}: впиши число три цифрой`, ['3'], { explain: 'Три пишется как 3.' }),
      order(`Урок ${n}: расставь шаги по порядку`, ['Услышать', 'Повторить', 'Прочитать']),
      match(`Урок ${n}: соедини пары`, [['один', '1'], ['два', '2'], ['три', '3']]),
      choose(`Урок ${n}: сколько дней в неделе?`, '7', ['5', '10'], { explain: 'В неделе семь дней.' }),
      read(`Прочитай вслух: cat, hat, mat (урок ${n})`),
    ],
    ...o,
  };
};

export default {
  id: 'enzero', title: 'Английский с нуля', icon: 'Aa', color: '#2563eb', zero: true, lang: 'english', after: 'english',
  resources: ['british-council', 'usa-learns', 'bbc-learning-english', 'duolingo', 'anki'],
  mentor: { name: 'Наставник', role: 'Тестовый курс', principles: ['Первое правило курса.', 'Второе правило курса.', 'Третье правило курса.', 'Четвёртое правило курса.'], prompts: ['Первый запрос.', 'Второй запрос.', 'Третий запрос.'] },
  intro: 'Тестовый маршрут для проверки экрана «С нуля»: пять уроков по цепочке.',
  plan: [{ week: 1, focus: 'Первая неделя', daily: '15 минут' }, { week: 2, focus: 'Вторая неделя', daily: '15 минут' }, { week: 3, focus: 'Третья неделя', daily: '15 минут' }, { week: 4, focus: 'Четвёртая неделя', daily: '15 минут' }],
  sources: ['Первый источник тестового курса', 'Второй источник тестового курса'],
  lessons: [lesson(1, []), lesson(2, ['ez-01']), lesson(3, ['ez-02']), lesson(4, ['ez-03']), lesson(5, ['ez-04'])],
};
